CREATE TABLE IF NOT EXISTS inv_receipts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, receipt_ref VARCHAR(80) NOT NULL UNIQUE, receipt_date DATE NOT NULL, branch_id INT UNSIGNED NOT NULL, supplier_id INT UNSIGNED NULL, document_ref VARCHAR(100) NULL, note VARCHAR(255) NULL, status ENUM('DRAFT','POSTED') NOT NULL DEFAULT 'DRAFT', created_by INT UNSIGNED NOT NULL, created_at DATETIME NOT NULL, posted_by INT UNSIGNED NULL, posted_at DATETIME NULL, CONSTRAINT fk_inv_receipt_branch FOREIGN KEY(branch_id) REFERENCES branches(id), CONSTRAINT fk_inv_receipt_supplier FOREIGN KEY(supplier_id) REFERENCES md_suppliers(id), KEY ix_inv_receipt_scope(branch_id,receipt_date,status)); CREATE TABLE IF NOT EXISTS inv_receipt_lines (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, receipt_id INT UNSIGNED NOT NULL, item_id INT UNSIGNED NOT NULL, quantity DECIMAL(18,3) NOT NULL, unit_price DECIMAL(18,2) NULL, created_at DATETIME NOT NULL, CONSTRAINT fk_inv_receipt_line_header FOREIGN KEY(receipt_id) REFERENCES inv_receipts(id) ON DELETE CASCADE, CONSTRAINT fk_inv_receipt_line_item FOREIGN KEY(item_id) REFERENCES md_items(id), CHECK(quantity>0)); INSERT IGNORE INTO permissions(code,name) VALUES ('inventory.receipt.view','Lihat barang masuk'),('inventory.receipt.create','Buat barang masuk'),('inventory.receipt.post','Posting barang masuk'); INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code='inventory.receipt.view' WHERE r.name IN ('Owner','Finance');